parameters.responseBody:
={{
`<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Your JobMonkey Mock Interview Report is Ready! 📄</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: Arial, sans-serif;
            line-height: 1.6;
            color: #2d3748;
            background-color: #f7fafc;
        }

        .email-container {
            max-width: 600px;
            margin: 20px auto;
            background: #FFFFFF;
            border-radius: 12px;
            overflow: hidden;
            border: 1px solid #C0E1FB;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.07);
        }

        .header {
            background: #015EC3;
            padding: 30px 20px;
            text-align: center;
            color: white;
        }

        .header h1 {
            font-size: 1.8rem;
            margin-bottom: 8px;
            font-weight: 700;
        }

        .header p {
            font-size: 1.1rem;
            opacity: 0.9;
        }

        .content {
            padding: 30px 25px;
        }

        .greeting {
            font-size: 1.1rem;
            margin-bottom: 25px;
            color: #4a5568;
        }

        .report-section {
            background: #f7fafc;
            border: 1px solid #C0E1FB;
            padding: 25px;
            border-radius: 10px;
            margin-bottom: 25px;
        }

        /* Styles for the AI-generated report content */
        .report-section h1 {
            font-size: 2rem;
            color: #015EC3;
            text-align: center;
            margin-bottom: 20px;
        }

        .report-section h2 {
            font-size: 1.3rem;
            color: #015EC3;
            border-bottom: 2px solid #C0E1FB;
            padding-bottom: 5px;
            margin-top: 25px;
            margin-bottom: 15px;
        }

        .report-section ul {
            list-style-position: inside;
            padding-left: 0;
        }

        .report-section li {
            margin-bottom: 10px;
            color: #4a5568;
        }

        .cta-section {
            text-align: center;
            margin: 30px 0;
        }

        .cta-btn {
            background: #015EC3;
            color: white;
            padding: 15px 30px;
            border: none;
            border-radius: 25px;
            font-size: 1.1rem;
            font-weight: 600;
            text-decoration: none;
            display: inline-block;
            box-shadow: 0 8px 20px rgba(1, 94, 195, 0.25);
            transition: transform 0.3s;
        }

        .cta-btn:hover {
            transform: translateY(-2px);
        }

        .social-section {
            background: #f7fafc;
            color: #2d3748;
            padding: 25px;
            border-radius: 10px;
            text-align: center;
            margin: 25px 0;
            border: 1px solid #C0E1FB;
        }

        .social-section h3 {
            color: #015EC3;
            margin-bottom: 10px;
        }

        .social-buttons {
            display: flex;
            justify-content: center;
            gap: 15px;
            margin-top: 20px;
            flex-wrap: wrap;
        }

        .social-btn {
            background: #015EC3;
            color: white;
            padding: 10px 20px;
            text-decoration: none;
            border-radius: 20px;
            font-weight: 500;
            transition: all 0.3s;
        }

        .social-btn:hover {
            background: #014b9b;
            transform: translateY(-2px);
        }

        .footer {
            background: #2d3748;
            color: #FFFFFF;
            padding: 25px;
            text-align: center;
        }

        .footer a {
            color: #C0E1FB;
            text-decoration: none;
        }

        @media (max-width: 600px) {
            .email-container {
                margin: 10px;
                border-radius: 8px;
            }
        }
    </style>
</head>
<body>
    <div class="email-container">
        <div class="header">
            <h1>📄 Your Mock Interview Report</h1>
            <p>Here's your personalized performance feedback from JobMonkey.</p>
        </div>

        <div class="content">
            <p class="greeting">Hi there, 👋</p>
            <p>Congratulations on completing your mock interview! We've analyzed your performance to provide you with actionable feedback. Please review your detailed report below.</p>

            <div class="report-section">
                ${$json.text}
            </div>

            <div class="cta-section">
                <p style="color: #718096; margin-bottom: 15px;">Ready to improve your score?</p>
                <a href="https://jobmonkey.dev/mock-interview/" class="cta-btn">Practice Again (10 Points)</a>
            </div>

            <div class="social-section">
                <h3>Found This Helpful? Share Your Progress!</h3>
                <p>Let your network know you're sharpening your interview skills with JobMonkey!</p>

                <div class="social-buttons">
                    <a href="https://twitter.com/intent/tweet?text=Just finished a mock interview with an AI coach on JobMonkey! Getting ready for my next big role. %23InterviewPrep %23JobMonkey %23AI" class="social-btn">Share on Twitter 🐦</a>
                    <a href="https://www.linkedin.com/sharing/share-offsite/?url=https://jobmonkey.dev" class="social-btn">Share on LinkedIn 💼</a>
                </div>
            </div>
        </div>

        <div class="footer">
            <p><strong>JobMonkey</strong></p>
            <p>Your AI-powered career co-pilot.</p>
            <br>
            <p>Questions? Reply to this email or visit our <a href="https://jobmonkey.dev/support">Support Page</a>.</p>
            <p style="font-size: 0.9rem; opacity: 0.8; margin-top: 15px;">
                You received this email because you used the mock interview tool.<br>
                © 2025 JobMonkey. All rights reserved.
            </p>
        </div>
    </div>
</body>
</html>
`
}}

